local _src = vim.fs.abspath(debug.getinfo(1).source:sub(2))
local _test_dir = vim.fs.dirname(_src)
package.path = _test_dir .. "/?.lua;" .. vim.fs.dirname(_test_dir) .. "/lua/?.lua;" .. package.path
local H = require "harness"
local core = require("zathura_cite.core")

local vault = "/home/ls/knowledge_library"
local tmp = vim.fn.tempname() .. "_zc"
vim.fn.mkdir(tmp, "p")
local function w(name, content)
  local p = tmp .. "/" .. name
  local f = io.open(p, "w"); f:write(content); f:close(); return p
end

H.describe("core.parse_drop_file", function()
  H.it("parses 3-line file with multi-line text", function()
    local d = core.parse_drop_file(w("a.txt", "3\n/tmp/a.pdf\nline one\nline two"))
    H.truthy(d)
    H.eq(d.page, 3); H.eq(d.file, "/tmp/a.pdf"); H.eq(d.text, "line one\nline two")
  end)
  H.it("2-line file -> empty text", function()
    local d = core.parse_drop_file(w("b.txt", "2\n/tmp/a.pdf"))
    H.truthy(d); H.eq(d.text, "")
  end)
  H.it("malformed -> nil", function()
    H.falsy(core.parse_drop_file(w("c.txt", "x\n/tmp/a.pdf")))
    H.falsy(core.parse_drop_file(w("d.txt", "1.5\n/tmp/a.pdf")))
    H.falsy(core.parse_drop_file(w("e.txt", "")))
    H.falsy(core.parse_drop_file(tmp .. "/nonexistent.txt"))
  end)
end)

H.describe("core.match_citation_line", function()
  H.it("matches own wikilink format (real file)", function()
    local m = core.match_citation_line('[[literature/2017_msckf_notes|2017_msckf_notes]] p.3: "x"', vault)
    H.truthy(m)
    H.eq(m.file, vault .. "/literature/2017_msckf_notes.pdf")
    H.eq(m.page, 3)
  end)
  H.it("wikilink with .pdf in target", function()
    local m = core.match_citation_line('[[literature/2017_msckf_notes.pdf]] p.1: "x"', vault)
    H.truthy(m); H.eq(m.page, 1)
  end)
  H.it("matches markdown link with abs path (file exists)", function()
    local pdf = w("ext.pdf", "%PDF-1.4 fake")
    local m = core.match_citation_line('[ext](' .. pdf .. ') p.7: "x"', vault)
    H.truthy(m); H.eq(m.file, pdf); H.eq(m.page, 7)
  end)
  H.it("no p.N -> nil", function()
    H.falsy(core.match_citation_line('[[literature/2017_msckf_notes|x]] quoted', vault))
  end)
  H.it("wikilink to .md target -> nil", function()
    H.falsy(core.match_citation_line('[[note/English_Vocabulary|vocab]] p.2: "x"', vault))
  end)
  H.it("ghost wikilink -> nil", function()
    H.falsy(core.match_citation_line('[[nowhere/ghost|ghost]] p.1: "x"', vault))
  end)
  H.it("markdown link to missing file -> nil", function()
    H.falsy(core.match_citation_line('[gone](/tmp/definitely_missing_zc.pdf) p.1: "x"', vault))
  end)
end)

H.describe("core.latest_drop", function()
  H.it("returns newest by name", function()
    w("20261003120000_1.txt", "1\n/f.pdf\nx")
    w("20261003120001_1.txt", "2\n/f.pdf\ny")
    H.eq(core.latest_drop(tmp), tmp .. "/20261003120001_1.txt")
  end)
  H.it("empty or missing dir -> nil", function()
    H.falsy(core.latest_drop(tmp .. "/nope"))
    local empty = vim.fn.tempname() .. "_zce"; vim.fn.mkdir(empty, "p")
    H.falsy(core.latest_drop(empty))
  end)
end)

H.run()
if vim.v.exception == "" then vim.fn.delete(tmp, "rf") end
